sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hotel-features {
  width: 100%;
  box-sizing: border-box;
  padding: 65px 7%;
  background: #ffffff;
  font-family: Arial, sans-serif;
}

.features-grid {
  max-width: 1300px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 35px;
}

.feature-item {
  text-align: center;
  padding: 15px;
}

.feature-icon {
  width: 65px;
  height: 65px;
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #e8eee9;
  color: #1f3a30;
  font-size: 23px;
}

.feature-item h3 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 22px;
  font-weight: normal;
  margin: 0 0 12px;
}

.feature-item p {
  color: #6f756f;
  font-size: 13px;
  line-height: 1.8;
  margin: 0;
}

@media (max-width: 850px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 25px;
  }
}

@media (max-width: 480px) {
  .features-grid {
    grid-template-columns: 1fr;
  }
}
